from scipy.signal import csd, decimate
def P3(d,Kf=16.99,Tp=0.1407,a=0.782,Ta=0.1015,Tg=0.0312):
    th=(d.th.values-d.th[0]); w=np.r_[0,np.diff(th)]/dt/wb
    Pc=d.P[0]-Kf*lag(w,Tp)+a*(d.Vs.values-lag(d.Vs.values,Ta))
    return d.V.values*lag(Pc/d.V.values,Tg)
def frf1(d,Pm,dec=10,aa=True):
    sig={'V':d.V.values,'th':d.th.values-d.th.values[0],'P':d.P.values,'M':Pm}
    if aa: sig={k:decimate(v,dec,ftype='fir') for k,v in sig.items()}
    else: sig={k:v[::dec] for k,v in sig.items()}
    S={}
    for a_ in ['V','th']:
        for b in ['V','th','P','M']:
            f,s=csd(sig[a_],sig[b],fs=1000/dec,nperseg=819,detrend='linear'); S[(a_,b)]=s
    out={}
    for o in ['P','M']:
        out[o]=np.array([np.linalg.solve(np.array([[S[('V','V')][k],S[('V','th')][k]],[S[('th','V')][k],S[('th','th')][k]]]),np.array([S[('V',o)][k],S[('th',o)][k]])) for k in range(len(f))])
    return f,out
